public int CharacterReplacement(string s, int k) {
    var count = new int[26];
    int l = 0, maxFreq = 0;
    for (int r = 0; r < s.Length; r++) {
        maxFreq = Math.Max(maxFreq, ++count[s[r] - 'A']);   // upwards only
        if (r - l + 1 - maxFreq > k)                        // slide, don't shrink
            count[s[l++] - 'A']--;
    }
    return s.Length - l;                                    // window length = answer
}

