// number of subarrays with at most k distinct numbers
int AtMost(int[] nums, int k) {
    var cnt = new Dictionary<int, int>();
    int l = 0, total = 0;
    for (int r = 0; r < nums.Length; r++) {
        cnt[nums[r]] = cnt.GetValueOrDefault(nums[r]) + 1;
        while (cnt.Count > k) {
            if (--cnt[nums[l]] == 0) cnt.Remove(nums[l]);
            l++;
        }
        total += r - l + 1;            // every valid window ending at r
    }
    return total;
}
// exactly k distinct = AtMost(k) - AtMost(k - 1)   (#992)
